            decision = "require_approval"
        else:
            decision = "refuse"
        if task.id in self._tasks:
            # An ID collision must not inherit the original task's authority.
            self._tasks[task.id] = "deny"
            return "deny"
        self._tasks[task.id] = decision
        return decision

